import 'dart:io';
import 'package:flutter/foundation.dart';
import 'package:flutter_local_notifications/flutter_local_notifications.dart';

class PermissionService {
  static final PermissionService _instance = PermissionService._internal();

  factory PermissionService() {
    return _instance;
  }

  PermissionService._internal();

  /// Fordert alle benötigten Berechtigungen beim App-Start an
  Future<void> requestInitialPermissions() async {
    try {
      // Nur auf Android Berechtigungen erforderlich
      if (Platform.isAndroid) {
        // Android 12+ erfordert POST_NOTIFICATIONS Permission
        // Das wird durch flutter_local_notifications automatisch gehandhabt
        if (kDebugMode) {
          print('✓ Permission Service initialized');
        }
      } else if (Platform.isIOS) {
        // iOS Notifications Permission
        final flutterLocalNotificationsPlugin = FlutterLocalNotificationsPlugin();
        final iosSettings = DarwinInitializationSettings(
          requestAlertPermission: true,
          requestBadgePermission: true,
          requestSoundPermission: true,
        );
        
        await flutterLocalNotificationsPlugin.resolvePlatformSpecificImplementation<
            IOSFlutterLocalNotificationsPlugin>()?.requestPermissions(
          alert: true,
          badge: true,
          sound: true,
        );
        
        if (kDebugMode) {
          print('✓ iOS notification permissions requested');
        }
      }
    } catch (e) {
      if (kDebugMode) {
        print('❌ Error requesting permissions: $e');
      }
    }
  }
}
